            modelBuilder.Entity("Arte.Core.Cases.Case", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uuid");

                    b.Property<Guid?>("AssetId")
                        .HasColumnType("uuid");

                    b.Property<Guid?>("AssigneeId")
                        .HasColumnType("uuid");

                    b.Property<string>("BodyNotes")
                        .HasMaxLength(500)
                        .HasColumnType("character varying(500)");

                    b.Property<string>("BodyStatus")
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)");

                    b.Property<DateTimeOffset?>("ClosedAt")
                        .HasColumnType("timestamp with time zone");

                    b.Property<DateTimeOffset?>("CreditDueAt")
                        .HasColumnType("timestamp with time zone");

                    b.Property<string>("CustodyStatus")
                        .IsRequired()
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)");

                    b.Property<Guid>("CustomerId")
                        .HasColumnType("uuid");

                    b.Property<DateTimeOffset?>("DeletedAt")
                        .HasColumnType("timestamp with time zone");

                    b.Property<Guid?>("DeletedBy")
                        .HasColumnType("uuid");

                    b.Property<string>("Diagnosis")
                        .HasMaxLength(4000)
                        .HasColumnType("character varying(4000)");

                    b.Property<long?>("EstimatedAmountRials")
                        .HasColumnType("bigint");

                    b.Property<short?>("FuelLevel")
                        .HasColumnType("smallint");

                    b.Property<JsonDocument>("IntakeChecklist")
                        .HasColumnType("jsonb");

                    b.Property<bool>("IsSample")
                        .HasColumnType("boolean");

                    b.Property<Guid?>("MergedIntoCaseId")
                        .HasColumnType("uuid");

                    b.Property<long>("Number")
                        .HasColumnType("bigint");

                    b.Property<int?>("OdometerKm")
                        .HasColumnType("integer");

                    b.Property<DateTimeOffset>("OpenedAt")
                        .HasColumnType("timestamp with time zone");

                    b.Property<Guid>("OpenedBy")
                        .HasColumnType("uuid");

                    b.Property<Guid?>("ParentCaseId")
                        .HasColumnType("uuid");

                    b.Property<DateTimeOffset?>("PromisedAt")
                        .HasColumnType("timestamp with time zone");

                    b.Property<string>("Relation")
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)");

                    b.PrimitiveCollection<string[]>("ReportedProblems")
                        .IsRequired()
                        .HasColumnType("text[]");

                    b.Property<string>("Request")
                        .IsRequired()
                        .HasMaxLength(2000)
                        .HasColumnType("character varying(2000)");

                    b.PrimitiveCollection<string[]>("RequestedServices")
                        .IsRequired()
                        .HasColumnType("text[]");

                    b.Property<DateTimeOffset>("StageEnteredAt")
                        .HasColumnType("timestamp with time zone");

                    b.Property<Guid>("StageId")
                        .HasColumnType("uuid");

                    b.Property<Guid>("TenantId")
                        .HasColumnType("uuid");

                    b.Property<string>("TrackingCode")
                        .HasMaxLength(16)
                        .HasColumnType("character varying(16)");

                    b.Property<uint>("Version")
                        .IsConcurrencyToken()
                        .ValueGeneratedOnAddOrUpdate()
                        .HasColumnType("xid")
                        .HasColumnName("xmin");

                    b.Property<string>("WaitReason")
                        .HasMaxLength(30)
                        .HasColumnType("character varying(30)");

                    b.Property<DateTimeOffset?>("WarrantyUntil")
                        .HasColumnType("timestamp with time zone");

                    b.Property<Guid>("WorkflowId")
                        .HasColumnType("uuid");

                    b.HasKey("Id");

                    b.HasIndex("AssetId");

                    b.HasIndex("AssigneeId");

                    b.HasIndex("CustomerId");

                    b.HasIndex("ParentCaseId");

                    b.HasIndex("StageId");

                    b.HasIndex("TrackingCode")
                        .IsUnique()
                        .HasFilter("\"TrackingCode\" IS NOT NULL");

                    b.HasIndex("WorkflowId");

                    b.HasIndex("TenantId", "AssetId");

                    b.HasIndex("TenantId", "AssigneeId");

                    b.HasIndex("TenantId", "CustomerId");

                    b.HasIndex("TenantId", "Number")
                        .IsUnique();

                    b.HasIndex("TenantId", "StageId");

                    b.ToTable("Cases");
                });

